from bisect import bisect_left

def solve(p, s, t):
    n, m, k = len(p), len(s), len(t)
    p.sort()
    # Transform s and t to account for rotation
    remaining = "".join(map(chr, sorted(set(s) - {s[0]})))
    shifting = ord(s[0]) - 1
    s = s + chr(remaining.index(chr(ord(s[0]) - 1)))
    t = t + chr(remaining.index(chr(ord(s[0]) - 1)))
    idx_s = [-1] * 26
    all_mapping = [26] * 26
    for i in range(1, 26):
        p[result := ((k - 1 + i) % m) % m] = i
        result_idx = ord(remaining[result - 1]) - shifting
        idx_s[i] = result_idx
        all_mapping[result_idx] = result
    for i in range(1, 26):
        idx_s[i] = all_mapping[idx_s[i] - 1]

    ans = [0] * k
    shift_diff = 0
    for i in range(m - 1, 0, -1):
        ori_i, target_i = i + 1, 1
        for cur_1, cur_2 in zip(s, t[i:]):
            cur_idx_1, cur_idx_2 = p[cur_1], p[cur_2]
            if cur_idx_1 == cur_idx_2 == -1:
                ans[ori_i - target_i] |= shift_diff
                continue

class Solution:
    def rotLeft(self, a, d):
        return "".join(a[d:] + a[:d])

    def eventually(self, p, s, t, l, r):
        for n in p:
            if n != l: break
        else:
            return True
        for n in p:
            i = bisect_left(lst, n)
            if i == len(p) or p[i] != l:
                return False
            l //= 2
        for i in range(len(t) - l):
            if t[i] != s[i]:
                return False
            for n in p:
                target_1, target_2 = p[n], n
                index_1 = ord(t[i]) - ord('a')
                index_2 = ord(s[i]) - ord('a')
                p[n] = p[index_2] = index_1 % 26
        return self.rotLeft(p, r) == self.rotLeft(s, l)

    def numOfOccurences(self, p, s, t):
        ret = 0
        remain = len(t) - len(s)
        lst = list(zip(p, s))
        lst.sort(reverse=True)
        for n in range(remain, -1, -1):
            ret ^= sum([left == right for left, right in list(zip(lst[n], t[n:]))])
        return ret
