import math

def find_tournament_scores(scores, duplicate_filter):
    n = len(scores)
    check_tournament = [0] * n
    total_elements_filtered = 0

    for i in range(n):
        if not check_tournament[i]:
            check_tournament[i] = 1
            j = scores[i]

            for j in range(i + 1, n):
                if scores[j] == j:
                    check_tournament[j] = 0
            total_elements_filtered += 1

            if total_elements_filtered >= duplicate_filter:
                break

    return n + 1 - total_elements_filtered

def is_tournament_possible(scores):
    n = len(scores)
    scores_set = set(scores)

    # Check if Landau's criterion is satisfied
    if not (all(x1 <= x2 for x1, x2 in zip(scores, scores[1:])))
        return None

    return find_tournament_scores(scores, 0)

def generate_tournament_scores(n, scores):
    tournament = [["0" for _ in range(n)] for _ in range(n)]
    cycle = 2 * math.ceil(n/2)

    up = 2 * cycle // 3
    down = cycle - up - 2

    for i in range(down):
        for j in range(i, cycle):
            tournament[i][j] = '1'
            tournament[j][i] = '1'

    for i in range(down):
        for j in range(cycle, i+down):
            if i < j:
                tournament[i][j] = '1'
            else:
                tournament[j][i] = '1'

    for i in range(cycle, up):
        for j in range(max(i+1,n)-1, cycle-1):
            tournament[i][j] = '1'
            tournament[j][i] = '1'

    return tournament

