from typing import List

def generate_new_matrices(matrix: List[List[int]], directions: List[str]) -> (List[List[int]], List[str]):
    n = len(matrix)
    m = len(matrix[0])
    new_matrix = [[0] * m for _ in range(n)]
    directions_used = [''] * m

    def dfs(row, col, pre_cost, pre_dir):
        if row < 0 or row >= n or col < 0 or col >= m:
            return 
        if matrix[row][col] == 0:
            return 
        new_matrix[row][col] = matrix[row][col] + pre_cost
        directions_used[col] = directions[row][col]
        dfs(row + 1, col, new_matrix[row][col], directions[row][col])
        dfs(row - 1, col, new_matrix[row][col], directions[row][col])
        dfs(row, col + 1, new_matrix[row][col], directions[row][col])
        dfs(row, col - 1, new_matrix[row][col], directions[row][col])
        if directions_used[col] == '':
