                        levels[char] += 1
                    elif levels[char] > 1:
                        levels[char] -= 1
            elif char.isalpha():
                level = levels.get(char, len(levels))
                levels[char] = level + 1
                level += 2
                while level > 3:
                    level -= 2
                    levels[char] = level + 1
            elif char == '$':
                continue
            elif char == '#' or char == '^' or char == '&':
                continue
            all_vars = [variable_name(name) for name in re.findall(variable_pattern, line) if name]
            if char == '$':
