import math
from itertools import combinations

def can_form_tournament(participants, sorted_points):
    points_dict = {}
    for i in range(len(sorted_points)):
        for j in range(i + 1, len(sorted_points)):
            if participants[i] % 2 == participants[j] % 2:
                points_dict[(sorted_points[i], sorted_points[j])] = 4
                points_dict[(sorted_points[j], sorted_points[i])] = 0
            else:
                points_dict[(sorted_points[i], sorted_points[j])] = 2
                points_dict[(sorted_points[j], sorted_points[i])] = 2

    def is_consistent(results, n, participants):
        points_count = [0] * len(participants)
        for i in range(len(results)):
            for j in range(participants[results[i][0] - 1], participants[results[i][1] - 1] + 1):
                points_count[j - 1] += points_dict[(i, j)]
        points_count.sort()
        for i in range(n):
            if points_count[i] != sorted_points[i]:
                return False
        return True

    nm = min(median(i) for i in combinations(sorted_points))
    m = max(participants)
    median = int(m / 2)
    r = int(n / median + 1)
    if r ** median < 20000:
        return 'no'

    def tau(n, m):
        return math.factorial(m) / (math.factorial(n) * math.factorial(m - n))

    cur_s = 0
    for i in range(1, m):
        temp_s = cur_s
        all_rest = int(tau(m - 1, i) * math.factorial(m) / math.factorial(n - 1))
        for j in range(n):
            v = tau(all_rest - (i - j), i) * tau(m - i - 1, n - j - 1)
            p = all_rest - (i - j)
            if p == 0:
                continue
            cur_s = math.floor(v * cur_s / m)
        cur_s = cur_s * all_rest + temp_s
        return cur_s

