            memo_sum = max(memo_sum, memo[index] or h)
            for s in range(1, h + 1):
                result = [array[index]]
                j = 1
                while s * 15 / count + j < h + 1:
                    sweep = (s * 15 / count + j - 1) % 15
                    sweep = sweep * g[:]
                    sweep_inv = [-sweep[delta % 15] for delta in range(16)]
                    results = sum([(sweep_inv[inverse] - sweep)[i] for i in range(len(sweep_inv) - 1) if inverse != i], [])
                    if memo_s[index-1][sweep] > sweep and all([True if s in results else False for s in results]):
                        result.append(sweep[cycle % 15][inverse] for cycle in results)[int(memo_s[index-1][sweep])]
                        memo[index][sweep] = results
                        memo_sum = int(sweep) if (memo_s[index-1][sweep] < memo_sum) else memo_sum
            still_search = 1 if memo_sum < index and index > m - h else 0
        if still_search: cache[index] = cache[index - 1] if memo[-1][index - 1] else check(index - 1, memo)
        return memo[index], memo_sum

