from collections import defaultdict

def restore_password(n, substrings):
    combination_counts = defaultdict(int)
    count_subset = set()

    for i in range(n):
        combination_counts[intersect(substrings[i], substrings[(i + 1) % n])] += 1
        subset_str = ''.join(sorted(substrings[i]))
        if subset_str in count_subset:
            return "NO"
        count_subset.add(subset_str)

    result = []
    prefix_length, suffix_length = 3, 1
    current = "".join(set(substrings[0]))

    while prefix_length <= len(current) and suffix_length <= len(current):
        if prefix_length - suffix_length < current.count(substrings[0][prefix_length - suffix_length]):
            prefix_length += 1
        else:
            suffix_length += 1

        prefix_set = set()
        current = current[prefix_length - suffix_length:prefix_length]

        if current in count_subset:
            result.append(current[:prefix_length - suffix_length])

    count_sequence = False
    for j in range(2, len(result)):
        sequence = ''.join(sorted(result[j]))
        if sequence not in count_subset:
            count_sequence = True

    if not count_sequence:
        return "YES\n".join(result) + "\n"
    return "NO"

def intersect(str1, str2):
    return "".join(sorted(set(str1) & set(str2)))

def check():
    assert restore_password(5, ["aca", "aba", "aba", "cab", "bac"]) == "YES\nabacaba\n"
    assert restore_password(4, ["abc", "bCb", "cb1", "b13"]) == "NO"
    assert restore_password(7, ["aaa", "aaa", "aaa", "aaa", "aaa", "aaa", "aaa"]) == "YES\naaaaaaaaa\n"

check()
