from collections import Counter

def find_min_tournament_size(scores):
    n = len(scores)
    counters = Counter()
    for i in range(n):
        counters[scores[i] - 1] += 1

    # Create a tournament with minimum possible number of vertices
    n_tournaments = 0
    for key in counters:
        if counters[key] == 1 and key != 0:
            counters[key] -= 1
            n_tournaments += 1

    # If all scores have only one occurrence, no tournament can be formed
    if n == n_tournaments:
        return "("(" * (n - 1) + ")"

    counters = Counter()
    output = []

    # Create the main diagonal of the tournament
    output.append("0" * n)

    # Initialize the rest of the tournament
    for i in range(n):
        for j in range(n):
            if i < j and j < i:
                output.append("0")
            else:
                counters[scores[i] - 1] += 1

    # Remove duplicates
    for key in counters:
        if counters[key] > 1:
            return "ERROR"

    return f"{n_tournaments}\n{''.join(output)}"
